const $ = (s, root = document) => root.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY = 'fluently.learning.v1';
const dateKey = (date = new Date()) => `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const freshState = () => ({version:1,name:'Learner',dailyGoal:15,completed:{},activities:[],practice:{},drafts:{},knownWords:[],placement:null,examResults:[]});
function cleanState(raw) {
  const s = freshState();
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) throw new Error('Invalid learning backup.');
  s.name = typeof raw.name === 'string' ? raw.name.slice(0,40) || 'Learner' : s.name;
  s.dailyGoal = [10,15,20,30].includes(Number(raw.dailyGoal)) ? Number(raw.dailyGoal) : 15;
  if(raw.completed && typeof raw.completed === 'object') for(const lesson of LESSONS){const entry=raw.completed[lesson.id];if(entry && typeof entry==='object' && Number.isFinite(entry.score))s.completed[lesson.id]={score:Math.max(0,Math.min(100,entry.score)),date:typeof entry.date==='string'?entry.date.slice(0,10):dateKey()};}
  if(Array.isArray(raw.activities))s.activities=raw.activities.filter(a=>a&&typeof a.id==='string'&&typeof a.title==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(a.date)&&Number.isFinite(a.xp)&&Number.isFinite(a.minutes)).slice(-2000).map(a=>({id:a.id.slice(0,200),title:a.title.slice(0,150),date:a.date,xp:Math.min(500,Math.max(0,a.xp)),minutes:Math.min(120,Math.max(0,a.minutes)),skill:typeof a.skill==='string'?a.skill.slice(0,30):'practice'}));
  if(raw.drafts && typeof raw.drafts === 'object')for(const [key,value] of Object.entries(raw.drafts).slice(0,1000)){if(typeof value==='string' && !['__proto__','constructor','prototype'].includes(key))s.drafts[key]=value.slice(0,50000);}
  if(raw.practice && typeof raw.practice==='object'&&!Array.isArray(raw.practice))s.practice=JSON.parse(JSON.stringify(raw.practice));
  if(Array.isArray(raw.knownWords))s.knownWords=raw.knownWords.filter(w=>WORDS.some(item=>item.word===w));
  if(raw.placement&&typeof raw.placement==='object')s.placement={level:LEVELS.some(l=>l.id===raw.placement.level)?raw.placement.level:'a0',score:Math.min(100,Math.max(0,Number(raw.placement.score)||0)),date:String(raw.placement.date||'').slice(0,10)};
  if(Array.isArray(raw.examResults))s.examResults=raw.examResults.filter(e=>e&&typeof e.title==='string'&&Number.isFinite(e.score)).slice(-100).map(e=>({title:e.title.slice(0,100),score:Math.max(0,Math.min(100,e.score)),date:String(e.date||'').slice(0,10)}));
  return s;
}
let storageUnavailable = false;
let state;
try { const raw=localStorage.getItem(KEY); state=raw?cleanState(JSON.parse(raw)):freshState(); } catch {state=freshState();storageUnavailable=true;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{if(!storageUnavailable){storageUnavailable=true;toast('Browser storage is unavailable. Export your progress before leaving.');}}}
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function awardActivity(id,xp,detail){
  const info=typeof detail==='string'?{title:detail}:detail||{};
  if(state.activities.some(a=>a.id===id&&a.date===dateKey())){toast('Already saved for today. Keep practising to build confidence.');return false;}
  state.activities.push({id,title:info.title||'Practice completed',xp:Number(xp)||10,minutes:info.minutes||5,skill:info.skill||'practice',date:dateKey()});
  if(state.activities.length>2000)state.activities.shift();save();const streakCount=$('.streak-top b');if(streakCount)streakCount.textContent=streak();toast(`Practice saved. One more step forward! +${Number(xp)||10} XP`);return true;
}
